-- AQC-Core — estimation item relationships (data model)
-- Generated by SchemaExport.BuildSql(); item→material composition + item→item derivation.

CREATE TABLE item (
  key      TEXT PRIMARY KEY,
  name     TEXT,
  unit     TEXT,
  category TEXT
);
CREATE TABLE material (
  key      TEXT PRIMARY KEY,
  name     TEXT,
  unit     TEXT,
  category TEXT
);
CREATE TABLE recipe (
  key        TEXT PRIMARY KEY,
  item_key   TEXT REFERENCES item(key),
  name       TEXT,
  dry_factor REAL,
  note       TEXT
);
CREATE TABLE recipe_component (
  id           TEXT PRIMARY KEY,
  recipe_key   TEXT REFERENCES recipe(key),
  material_key TEXT REFERENCES material(key),
  parts        REAL
);
CREATE TABLE item_material (
  id           TEXT PRIMARY KEY,
  item_key     TEXT REFERENCES item(key),
  material_key TEXT REFERENCES material(key),
  note         TEXT
);
CREATE TABLE link_rule (
  id            TEXT PRIMARY KEY,
  name          TEXT,
  source_item   TEXT REFERENCES item(key),
  target_item   TEXT REFERENCES item(key),
  basis         TEXT,
  factor        REAL,
  rate_code     TEXT,
  rate_override REAL
);
CREATE TABLE derived_item (
  id          TEXT PRIMARY KEY,
  rule_id     TEXT REFERENCES link_rule(id),
  source_item TEXT REFERENCES item(key),
  target_item TEXT REFERENCES item(key),
  source_qty  REAL,
  factor      REAL,
  target_qty  REAL,
  target_unit TEXT
);

